<div class="page-header mb-4"><div class="row align-items-center"><div class="col"><h2 class="page-title">الأدوار</h2></div><div class="col-auto"><a class="btn btn-primary" href="/access/roles/create"><i class="ti ti-plus ms-2"></i>إضافة دور</a></div></div></div>
<div class="card"><div class="table-responsive"><table class="table table-vcenter card-table"><thead><tr><th>الدور</th><th>الكود</th><th>المستخدمون</th><th>الصلاحيات</th><th>الحالة</th><th></th></tr></thead><tbody><?php foreach($roles as $role):?><tr><td><?=e($role['name'])?> <?= $role['is_system']?'<span class="badge bg-blue-lt">نظام</span>':'' ?></td><td><code><?=e($role['code'])?></code></td><td><?=(int)$role['users_count']?></td><td><?=(int)$role['permissions_count']?></td><td><?= $role['is_active']?'نشط':'معطّل' ?></td><td><?php if(!$role['is_system']):?><a class="btn btn-sm btn-outline-primary" href="/access/roles/<?=$role['id']?>/edit">تعديل</a> <a class="btn btn-sm btn-outline-secondary" href="/access/roles/<?=$role['id']?>/permissions">الصلاحيات</a><?php else:?><span class="text-secondary">محمي</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
